import { useState } from "react";

function HoSo() {
  const [sv, setSv] = useState({ ten: "An", diem: 8 });
  return (
    <div>
      <p>{sv.ten}: {sv.diem}</p>
      <button onClick={() => setSv({ ...sv, diem: sv.diem + 1 })}>
        Cong diem
      </button>
    </div>
  );
}

export default HoSo;
